(3273477, 454583, 62727, '<td valign="top">He''s making a grand entrance! 7</td>', 'He''s making a grand entrance! 7', '2007-01-24 00:44:32.000000', NULL, 1),
(3273486, 455015, 60505, '<td valign="top">not enough resolution in this photo to rate highly. composition weak, little to hold the eye. too little contrast in the photo- too monochromatic. watch how your eye wanders around the photo to search for something there. Nothing much found in this photo a frustrating experience. not enjoyable as you suggest!</td>', 'not enough resolution in this photo to rate highly. composition weak, little to hold the eye. too little contrast in the photo- too monochromatic. watch how your eye wanders around the photo to search for something there. Nothing much found in this photo a frustrating experience. not enjoyable as you suggest!', '2007-01-24 00:46:09.000000', NULL, 1),
