(3273489, 455989, 62727, '<td valign="top">Stunning!  8</td>', 'Stunning!  8', '2007-01-24 00:46:42.000000', NULL, 1),
(3273493, 455989, 19982, '<td valign="top">Man, I really wish this were in another challenge.  I think it is an absolutely gorgeous, just not truly "fitting" as an entrance.  What I mean is ... if it weren''t for your title, I''d have no idea that this was any kind of entrance and the image really needs to speak for itself.  But in any case, kudos on an awesome image!</td>', 'Man, I really wish this were in another challenge.  I think it is an absolutely gorgeous, just not truly "fitting" as an entrance.  What I mean is ... if it weren''t for your title, I''d have no idea that this was any kind of entrance and the image really needs to speak for itself.  But in any case, kudos on an awesome image!', '2007-01-24 00:46:54.000000', NULL, 1),
