(3273707, 456255, 69008, '<td valign="top">Impressive depth of field.</td>', 'Impressive depth of field.', '2007-01-24 01:45:39.000000', NULL, 1),
(3273711, 456989, 57378, '<td valign="top">Nice angle but a little heavy on the post processing.</td>', 'Nice angle but a little heavy on the post processing.', '2007-01-24 01:46:55.000000', NULL, 1),
(3273717, 457461, 57378, '<td valign="top">Nice and striking - Good B and W</td>', 'Nice and striking - Good B and W', '2007-01-24 01:49:38.000000', NULL, 1),
(3273720, 457142, 57378, '<td valign="top">Great post processing and an interesting image - Very nice.</td>', 'Great post processing and an interesting image - Very nice.', '2007-01-24 01:50:55.000000', NULL, 1),
(3273724, 457503, 6804, '<td valign="top">Awesome work!!!<br/>This is one of my top three highest rated shots for this challenge.  This is the type of image I truly wish I had the ability to see in the subjects I shoot.  I just can''t make a small item like this tell a story.  You''ve pulled it off with flying colors.  The title is a nice compliment and fits the subject well, but this capture stands strong on it''s own and meets the challenge better than most.  Your depth of field is perfect in my opinion.  Its almost as if you are focusing on the dark area on the other side of the door and really does a great job of pointing the viewer to see what is beyond the door.  Excellent in every way!!!  10</td>', 'Awesome work!!!This is one of my top three highest rated shots for this challenge.  This is the type of image I truly wish I had the ability to see in the subjects I shoot.  I just can''t make a small item like this tell a story.  You''ve pulled it off with flying colors.  The title is a nice compliment and fits the subject well, but this capture stands strong on it''s own and meets the challenge better than most.  Your depth of field is perfect in my opinion.  Its almost as if you are focusing on the dark area on the other side of the door and really does a great job of pointing the viewer to see what is beyond the door.  Excellent in every way!!!  10', '2007-01-24 01:52:10.000000', NULL, 1),
(3273730, 457386, 57378, '<td valign="top">Nice - Great pattern and that tiny figure just adds some great detail - Well done</td>', 'Nice - Great pattern and that tiny figure just adds some great detail - Well done', '2007-01-24 01:54:31.000000', NULL, 1),
(3273734, 454384, 6804, '<td valign="top">Excellent entry for this challenge!!!  <br/>I really like detail and the coloring you''ve selected.  The subject is perfect and to the point.  10 from me and one of my three highest rated of the challenge.   Good luck!!!</td>', 'Excellent entry for this challenge!!!  I really like detail and the coloring you''ve selected.  The subject is perfect and to the point.  10 from me and one of my three highest rated of the challenge.   Good luck!!!', '2007-01-24 01:56:11.000000', NULL, 1),
(3273739, 457199, 52130, '<td valign="top">haha! I did that when I was little. Luckily I didn''t see anything, and my mom said that she was being "tickled"...oh my. Good idea and lighting.</td>', 'haha! I did that when I was little. Luckily I didn''t see anything, and my mom said that she was being "tickled"...oh my. Good idea and lighting.', '2007-01-24 01:57:24.000000', NULL, 1),
(3273751, 454629, 57378, '<td valign="top">I love this image - As a fisherman it couldn''t be better - The smooth ripples and the exposure is great - Is it pushing the "Entrance" theme? Maybe just a bit but I do love it. Well done</td>', 'I love this image - As a fisherman it couldn''t be better - The smooth ripples and the exposure is great - Is it pushing the "Entrance" theme? Maybe just a bit but I do love it. Well done', '2007-01-24 02:07:54.000000', NULL, 1),
(3273755, 456270, 57378, '<td valign="top">This has all the ingredients for a great image but I feel it may have been missed. Such a shame you could not get up to that fence and shoot over it as it really does pose a barrier to this picture. Exposure is great but I feel we could do with seeing a little more of the train. This is an amazing setting and I think you could have made this good picture great.</td>', 'This has all the ingredients for a great image but I feel it may have been missed. Such a shame you could not get up to that fence and shoot over it as it really does pose a barrier to this picture. Exposure is great but I feel we could do with seeing a little more of the train. This is an amazing setting and I think you could have made this good picture great.', '2007-01-24 02:10:02.000000', NULL, 1),
(3273770, 455989, 57378, '<td valign="top">Ouch - Great contrast.</td>', 'Ouch - Great contrast.', '2007-01-24 02:14:30.000000', NULL, 1),
