(3281252, 457687, 72423, '<td valign="top">Yep, this is an entrance, or an exit...  Nicely composed/cropped. Just a wee bit dull.</td>', 'Yep, this is an entrance, or an exit...  Nicely composed/cropped. Just a wee bit dull.', '2007-01-25 12:26:53.000000', NULL, 1),
(3281258, 457142, 30049, '<td valign="top">This is interesting and odd at the same time.  I like the way you''ve put this together, it''s engaging.  The odd part is the colors look blurred in the area past the gate, like it''s blurred motion of leaves blowing in a breeze combined with a long exposure?  Hmmm...hope you have comments on this to read after the challenge is finished.  Curious minds want to know.  :D  Good luck in the challenge.</td>', 'This is interesting and odd at the same time.  I like the way you''ve put this together, it''s engaging.  The odd part is the colors look blurred in the area past the gate, like it''s blurred motion of leaves blowing in a breeze combined with a long exposure?  Hmmm...hope you have comments on this to read after the challenge is finished.  Curious minds want to know.  :D  Good luck in the challenge.', '2007-01-25 12:28:14.000000', NULL, 1),
(3281263, 456924, 30049, '<td valign="top">Nice tones.  Cool door.  Wish it was a little sharper.  Good luck in the challenge.</td>', 'Nice tones.  Cool door.  Wish it was a little sharper.  Good luck in the challenge.', '2007-01-25 12:30:19.000000', NULL, 1),
(3281264, 457068, 48471, '<td valign="top">Good choice of colours, nicely done. Also, a good choice of angle (I mean, looking from down there).</td>', 'Good choice of colours, nicely done. Also, a good choice of angle (I mean, looking from down there).', '2007-01-25 12:31:42.000000', NULL, 1),
