(3281376, 455449, 69008, '<td valign="top">Ok snapshot, but I don''t connect it with the challenge theme.</td>', 'Ok snapshot, but I don''t connect it with the challenge theme.', '2007-01-25 13:10:46.000000', NULL, 1),
(3281435, 457069, 62318, '<td valign="top">The lighting and exposure are great in this photo. I love the long shadow of the door handle. Quite a bit of barrel distortion, but no fault of your own. While I think it is a simple composition, I think it would work even more if were more basic. Example, the carpet odesn''t help that much, nor the left wall. I would be tempted to make this B&amp;W. It is a great control of exposure and technical skill though. Above average rating.</td>', 'The lighting and exposure are great in this photo. I love the long shadow of the door handle. Quite a bit of barrel distortion, but no fault of your own. While I think it is a simple composition, I think it would work even more if were more basic. Example, the carpet odesn''t help that much, nor the left wall. I would be tempted to make this B&W. It is a great control of exposure and technical skill though. Above average rating.', '2007-01-25 13:34:50.000000', NULL, 1),
(3281460, 456924, 60805, '<td valign="top">Nicely done</td>', 'Nicely done', '2007-01-25 13:42:13.000000', NULL, 1),
