(3282590, 457731, 51538, '<td valign="top">Very funny - but not a great photo ;-)</td>', 'Very funny - but not a great photo ;-)', '2007-01-25 19:38:25.000000', NULL, 1),
(3282607, 456027, 23484, '<td valign="top">Go Tigers...All the way this year.</td>', 'Go Tigers...All the way this year.', '2007-01-25 19:41:01.000000', NULL, 1),
(3282612, 457364, 51538, '<td valign="top">Air enters the stomata, not water.  Back to botany 101.  Stomata are mostly on the underside of the leaf too.</td>', 'Air enters the stomata, not water.  Back to botany 101.  Stomata are mostly on the underside of the leaf too.', '2007-01-25 19:41:29.000000', NULL, 1),
(3282622, 457308, 51538, '<td valign="top">HG Wells would be proud of those robots in the background... I always think when looking off the promenade.</td>', 'HG Wells would be proud of those robots in the background... I always think when looking off the promenade.', '2007-01-25 19:42:49.000000', NULL, 1),
