(3282681, 457407, 60340, '<td valign="top">it is a pit the cat is out of focus, but they do move quite quickly.  The shadow on the right is a bit distracting too.</td>', 'it is a pit the cat is out of focus, but they do move quite quickly.  The shadow on the right is a bit distracting too.', '2007-01-25 19:55:52.000000', NULL, 1),
(3282687, 455900, 60495, '<td valign="top">Not sure I wanted to see the entrance shot either but it did make me laugh!</td>', 'Not sure I wanted to see the entrance shot either but it did make me laugh!', '2007-01-25 19:57:07.000000', NULL, 1),
(3282697, 454629, 60340, '<td valign="top">Sorry, what is it?</td>', 'Sorry, what is it?', '2007-01-25 19:59:35.000000', NULL, 1),
