(3290023, 456869, 72167, '<td valign="top">something about the exposure bothers me, too dark perhaps. But it''s a nioce theme with a reasonable execution</td>', 'something about the exposure bothers me, too dark perhaps. But it''s a nioce theme with a reasonable execution', '2007-01-27 04:15:42.000000', NULL, 1),
(3290024, 455808, 72167, '<td valign="top">a shot to make us think. "Making an Entrance" for sure. Nice</td>', 'a shot to make us think. "Making an Entrance" for sure. Nice', '2007-01-27 04:16:24.000000', NULL, 1),
(3290025, 457068, 72167, '<td valign="top">scary entrance, an interesting variation.</td>', 'scary entrance, an interesting variation.', '2007-01-27 04:16:50.000000', NULL, 1),
(3290028, 454445, 72167, '<td valign="top">this is a nothing photo when it comes to the theme. more a detailed look at some disaster.</td>', 'this is a nothing photo when it comes to the theme. more a detailed look at some disaster.', '2007-01-27 04:18:18.000000', NULL, 1),
(3290029, 456464, 72167, '<td valign="top">ok, but a little trite. See all the way through, nice exposure.</td>', 'ok, but a little trite. See all the way through, nice exposure.', '2007-01-27 04:18:49.000000', NULL, 1),
(3290031, 457609, 72167, '<td valign="top">if she was on the other side perhaps, seek entrance it''d work. I like the high key look, however.</td>', 'if she was on the other side perhaps, seek entrance it''d work. I like the high key look, however.', '2007-01-27 04:19:27.000000', NULL, 1),
