(3290381, 457714, 16402, '<td valign="top">Sorry, just too abstract for me. I can''t tell where/what the "entrance" connection is.</td>', 'Sorry, just too abstract for me. I can''t tell where/what the "entrance" connection is.', '2007-01-27 09:28:07.000000', NULL, 1),
(3290383, 456817, 16402, '<td valign="top">Great composition and color/tone. 7</td>', 'Great composition and color/tone. 7', '2007-01-27 09:29:22.000000', NULL, 1),
