(3290410, 456949, 16402, '<td valign="top">Like all the leading lines (footprints, stair rails, horizon) to the cabin.</td>', 'Like all the leading lines (footprints, stair rails, horizon) to the cabin.', '2007-01-27 09:44:17.000000', NULL, 1),
